import java.util.*;

class MedianFinder {
    private final List<Integer> data = new ArrayList<>();

    public MedianFinder() {
    }

    public void addNum(int num) {
        data.add(num);
    }

    public double findMedian() {
        Collections.sort(data);
        int n = data.size();
        if (n % 2 == 1) return (double) data.get(n / 2);
        return (data.get(n / 2 - 1) + data.get(n / 2)) / 2.0;
    }
}

import java.util.*;

class MedianFinder {
    private final List<Integer> data = new ArrayList<>();

    public MedianFinder() {
    }

    public void addNum(int num) {
        int pos = Collections.binarySearch(data, num);
        if (pos < 0) pos = -pos - 1;
        data.add(pos, num);
    }

    public double findMedian() {
        int n = data.size();
        if (n % 2 == 1) return (double) data.get(n / 2);
        return (data.get(n / 2 - 1) + data.get(n / 2)) / 2.0;
    }
}

import java.util.*;

class MedianFinder {
    private final PriorityQueue<Integer> left = new PriorityQueue<>(Collections.reverseOrder());
    private final PriorityQueue<Integer> right = new PriorityQueue<>();

    public MedianFinder() {
    }

    public void addNum(int num) {
        left.offer(num);
        right.offer(left.poll());
        if (right.size() > left.size()) {
            left.offer(right.poll());
        }
    }

    public double findMedian() {
        if (left.size() > right.size()) return (double) left.peek();
        return (left.peek() + right.peek()) / 2.0;
    }
}
